from lib import *
S = SS('n23')
steps = [
    step("errors.go 里一个 Error 有 Err、Type、Meta 三个字段;错误类型是 uint64 的位标志:Bind = 1<<63、Render = 1<<62、Private = 1<<0、Public = 1<<1、Any = 全 1。c.Error 的流程:err 为 nil 就 panic(\"err is nil\");用 errors.As 看它是不是已经是 *gin.Error,不是就包成 Type=Private 的新 *Error;追加到 c.Errors 并返回这个 *Error(可以链式 SetType / SetMeta)。", t=tl(S(1)), mark=lidx(S(1), 'ErrorTypePrivate ErrorType = 1 << 0', 'ErrorTypePublic ErrorType = 1 << 1', 'panic("err is nil")', 'errors.As(err, &parsedError)'), done=lidx(S(1), 'ErrorTypeBind ErrorType = 1 << 63', 'c.Errors = append(c.Errors, parsedError)'), kv=KV([['Private', '默认类型(1<<0)'], ['Public', '(1<<1),可以安全展示给客户端'], ['已是 *gin.Error', '不重复包装,返回原指针']], ['已是 *gin.Error'])),
    step("c.Error(普通 error) → Type=1(Private),返回的指针就是存进 Errors 的那个;c.Error(fmt.Errorf(\"外层: %w\", pub)) 里能用 errors.As 找到原来的 *gin.Error,返回的就是原指针 pub(Type=2),于是同一个 *Error 在 Errors 里出现了 2 次,共 3 条。ByType(Public) 2 条、ByType(Private) 1 条、ByType(Any) 3 条;String() 逐条输出 Error #01 …,有 Meta 时多一行 Meta:;MarshalJSON() 是数组 [{\"error\":…},{\"code\":1001,\"error\":…},…],只有一条时变成对象。", t=tl(S(2)), mark=lidx(S(2), '同一个指针存进 Errors', '返回的指针就是原来的', 'len(c.Errors)=3', 'panic: err is nil'), done=lidx(S(2), 'ByType(Public) 有 2 条', 'Error #01', 'MarshalJSON()', '只有一个 Private 时'), kv=KV([['3 条', '普通 + 公开 + 同一个公开的第二次'], ['String()', 'Error #01: … / Meta: …'], ['JSON()', '一条是对象,多条是数组']], ['3 条'])),
    step("框架自己放进 c.Errors 的:c.Bind(MustBindWith)失败 → 1 条,Type=1<<63(ErrorTypeBind),IsAborted=true,状态 400 已写出;c.ShouldBind 失败 → 0 条,不终止、不写;c.JSON 序列化失败(channel)→ 1 条 Type=1(Private),IsAborted=true,状态仍是 200 且还没写出。ErrorTypeRender 常量虽然注释写着用于渲染失败,Gin 自己并没有用它(渲染失败走的是普通的 c.Error)。", t=tl(S(3)), mark=lidx(S(3), 'c.Bind 失败', 'c.JSON 序列化失败'), done=lidx(S(3), 'c.ShouldBind 失败'), kv=KV([['c.Bind 失败', 'Bind 类型 + 400 + Abort'], ['c.ShouldBind 失败', '什么都不做,交给你'], ['渲染失败', 'Private 类型,Abort,状态没写出']], ['渲染失败'])),
    step("统一的错误处理中间件:handler 只 c.Error,中间件在 Next 之后检查:没有错误或响应已写出(c.Writer.Written())就什么都不做;有 Public 错误就 400 + JSON(只带 Public 的,内部的 redis 错误不会泄漏);只有 Private 错误就 500 + 固定的“服务器内部错误”。/pub → 400 带 field;/priv → 500 不暴露 dsn;/early 写完才出错 → 保持 200。", t=tl(S(4)), mark=lidx(S(4), '/pub', '/priv'), done=lidx(S(4), '/ok', '/early'), kv=KV([['Public', '展示给客户端'], ['Private', '只记日志,客户端看固定文案'], ['已写出', '中间件不再改响应']], ['Private'])),
    step("Logger 中间件会把 Private 错误打进访问日志:一个请求里 c.Error 了“私有错误 A”、一个 Public 的“公开错误 B”和“私有错误 C”,日志除了访问行,只多出 Error #01: 私有错误 A 和 Error #02: 私有错误 C 两行,Public 的没有出现(Logger 里 ErrorMessage = c.Errors.ByType(ErrorTypePrivate).String())。", t=tl(S(5)), mark=lidx(S(5), 'Error #01: 私有错误 A', 'Error #02: 私有错误 C'), done=lidx(S(5), '[GIN]'), kv=KV([['Private', '写进访问日志'], ['Public', '不写日志,应该展示给客户端'], ['编号', '按 Private 内部重新编号 #01 #02']], ['Private'])),
]
A = mkartn('n23', 23, 'Gin,c.Error,c.Errors,错误处理,ErrorType,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测 c.Error 与 c.Errors:Private / Public 类型;包装过的 *gin.Error 不会重复包装;c.Bind 失败是 Bind 类型并 400 终止、ShouldBind 失败不放进 Errors;ErrorTypeRender 常量实际没被使用;统一错误处理中间件的写法;Logger 只打印 Private 错误。',
    'handler 里遇到错误,是直接 c.JSON 返回,还是 c.Error 交给中间件?Gin 的 c.Errors 到底收集什么、Private 和 Public 有什么区别、框架自己会往里放什么?这篇把这些细节试出来,再写一个只暴露 Public 错误的统一处理中间件。',
    [('3 条', '两次 c.Error + 一次包装后的 c.Error,Errors 里的条数(同一个 *Error 出现了 2 次)'), ('1<<63', 'c.Bind 失败时放进 c.Errors 的类型(ErrorTypeBind);ShouldBind 失败不放'), ('2 条', '含 1 个 Public、2 个 Private 错误时,访问日志里多出的错误行数')],
    [('Error 的结构与 c.Error', '<p>一个 <code>*gin.Error</code> 由底层 <code>Err</code>、类型 <code>Type</code>(位标志)和任意 <code>Meta</code> 组成。<code>c.Error</code> 先用 <code>errors.As</code> 找一个已有的 <code>*gin.Error</code>(所以 <code>%w</code> 包装过也认得),找不到才新建一个 Private 的。返回的指针可以继续 <code>SetType</code> / <code>SetMeta</code>。传 nil 会 panic。</p>'),
     ('Errors 的各种读取方式', '<p><code>ByType</code> 按位标志过滤,<code>Last</code> 取最后一条,<code>Errors()</code> 得到字符串切片,<code>String()</code> 得到“Error #01 …”样式的多行文本,<code>JSON()</code> 一条时是对象、多条时是数组,Meta 里的字段会摊平进对象。注意同一个指针 <code>c.Error</code> 两次就会出现两次。</p>'),
     ('框架自己放什么', '<p><code>c.Bind</code> 系列(MustBindWith)失败时用 <code>AbortWithError(400, err).SetType(ErrorTypeBind)</code>,所以既写了 400 又终止了链;<code>ShouldBind</code> 系列不碰 <code>c.Errors</code>,由你决定怎么处理。渲染(如 <code>c.JSON</code> 序列化 channel)失败时用普通的 <code>c.Error</code> 并 <code>Abort</code>,状态还没写出。<code>ErrorTypeRender</code> 这个常量在源码里没有被使用。</p>'),
     ('统一错误处理', '<p>常见写法:handler 只负责 <code>c.Error(...)</code> 并 return,在最外层中间件的 <code>Next</code> 之后统一写响应。要点有三个:先判断 <code>c.Writer.Written()</code>,别在已经写出响应的情况下再写;只把 Public 类型展示给客户端;Private 错误留给日志,客户端只看固定文案,这样数据库 DSN 之类的内部信息不会泄漏。</p>'),
     ('Logger 与 Private 错误', '<p>Gin 的 <code>Logger</code> 在访问日志后面追加所有 Private 错误(<code>c.Errors.ByType(ErrorTypePrivate).String()</code>),Public 错误不会出现在日志里——所以想让某个错误既展示给客户端又进日志,需要自己在中间件里记录。</p>')],
    steps,
    [ENV_N_GIN + '。请求用 httptest 直接调用 ServeHTTP;Logger 的输出用 gin.LoggerWithWriter 写进 bytes.Buffer;每种情形各一次',
     '没有验证:Error.Meta 为结构体或指针时 JSON() 的输出;errors.Join 的多错误处理;自定义 LoggerFormatter 下 ErrorMessage 的使用;Public 错误里放内部信息的泄漏风险(只是设计建议)'],
    '错误收集')
